From 2f99b48b76aea6f6ba7c4f358bde09a6fa08deb2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:55:46 +0100
Subject: [PATCH] daemon/powerprofile: show the OSD when the profile changes
 externally

The power profile OSD only appeared for Plasma's own shortcut, so a switch
made by a laptop's profile key or another tool went unnoticed. Changes not
requested by PowerDevil or caused by profile holds now show it, debounced.

BUG: 526165
---
 daemon/actions/bundled/powerprofile.cpp | 49 +++++++++++++++++++++----
 daemon/actions/bundled/powerprofile.h   |  5 +++
 2 files changed, 47 insertions(+), 7 deletions(-)

diff --git a/daemon/actions/bundled/powerprofile.cpp b/daemon/actions/bundled/powerprofile.cpp
index 08fa40dba..0e1fb317f 100644
--- a/daemon/actions/bundled/powerprofile.cpp
+++ b/daemon/actions/bundled/powerprofile.cpp
@@ -19,6 +19,8 @@
 #include <KLocalizedString>
 #include <KPluginFactory>

+#include <QTimer>
+
 using namespace PowerDevil::BundledActions;

 K_PLUGIN_CLASS_WITH_JSON(PowerProfile, "powerdevilpowerprofileaction.json")
@@ -37,9 +39,19 @@ PowerProfile::PowerProfile(QObject *parent)
     , m_powerProfilesInterface(new OrgFreedesktopUPowerPowerProfilesInterface(ppdName, ppdPath, QDBusConnection::systemBus(), this))
     , m_powerProfilesPropertiesInterface(new OrgFreedesktopDBusPropertiesInterface(ppdName, ppdPath, QDBusConnection::systemBus(), this))
     , m_holdWatcher(new QDBusServiceWatcher(QString(), QDBusConnection::sessionBus(), QDBusServiceWatcher::WatchForUnregistration, this))
+    , m_externalChangeTimer(new QTimer(this))
 {
     new PowerProfileAdaptor(this);

+    // Skip short-lived values, e.g. while a profile daemon switches through an intermediate profile
+    m_externalChangeTimer->setSingleShot(true);
+    m_externalChangeTimer->setInterval(500);
+    connect(m_externalChangeTimer, &QTimer::timeout, this, [this] {
+        if (m_currentProfile != m_profileBeforeExternalChange) {
+            showIndicator(m_currentProfile);
+        }
+    });
+
     connect(m_holdWatcher, &QDBusServiceWatcher::serviceUnregistered, this, &PowerProfile::serviceUnregistered);
     connect(m_powerProfilesPropertiesInterface, &OrgFreedesktopDBusPropertiesInterface::PropertiesChanged, this, &PowerProfile::propertiesChanged);
     connect(m_powerProfilesInterface, &OrgFreedesktopUPowerPowerProfilesInterface::ProfileReleased, this, [this](unsigned int cookie) {
@@ -138,6 +150,9 @@ QList<QVariantMap> PowerProfile::profileHolds() const

 void PowerProfile::setProfile(const QString &profile, ProfileIndicatorVisibility indicatorVisibility)
 {
+    if (profile != m_currentProfile) {
+        m_requestedProfile = profile;
+    }
     auto call = m_powerProfilesPropertiesInterface->Set(m_powerProfilesInterface->interface(), activeProfileProperty, QDBusVariant(profile));
     bool needsReply = calledFromDBus();
     QDBusMessage receivedMsg;
@@ -146,8 +161,11 @@ void PowerProfile::setProfile(const QString &profile, ProfileIndicatorVisibility
         receivedMsg = message();
     }
     auto watcher = new QDBusPendingCallWatcher(call);
-    connect(watcher, &QDBusPendingCallWatcher::finished, this, [watcher, needsReply, receivedMsg, profile, indicatorVisibility] {
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher, needsReply, receivedMsg, profile, indicatorVisibility] {
         watcher->deleteLater();
+        if (watcher->isError() && m_requestedProfile == profile) {
+            m_requestedProfile.clear();
+        }
         if (needsReply) {
             if (watcher->isError()) {
                 QDBusConnection::sessionBus().send(receivedMsg.createErrorReply(watcher->error()));
@@ -156,16 +174,21 @@ void PowerProfile::setProfile(const QString &profile, ProfileIndicatorVisibility
             }
         }
         if (indicatorVisibility == ProfileIndicatorVisibility::ShowIndicator && !watcher->isError()) {
-            QDBusMessage osdMsg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
-                                                                 QStringLiteral("/org/kde/osdService"),
-                                                                 QStringLiteral("org.kde.osdService"),
-                                                                 QLatin1String("powerProfileChanged"));
-            osdMsg << profile;
-            QDBusConnection::sessionBus().asyncCall(osdMsg);
+            showIndicator(profile);
         }
     });
 }

+void PowerProfile::showIndicator(const QString &profile)
+{
+    QDBusMessage osdMsg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                         QStringLiteral("/org/kde/osdService"),
+                                                         QStringLiteral("org.kde.osdService"),
+                                                         QLatin1String("powerProfileChanged"));
+    osdMsg << profile;
+    QDBusConnection::sessionBus().asyncCall(osdMsg);
+}
+
 unsigned int PowerProfile::holdProfile(const QString &profile, const QString &reason, const QString &applicationId)
 {
     if (!m_profileChoices.contains(profile)) {
@@ -225,8 +248,19 @@ void PowerProfile::readProperties(const QVariantMap &properties)
     if (properties.contains(activeProfileProperty)) {
         QString newCurrentProfile = properties[activeProfileProperty].toString();
         if (m_currentProfile != newCurrentProfile) {
+            // e.g. a laptop's profile key; our own requests and profile holds are not announced
+            const bool external = !m_currentProfile.isEmpty() && newCurrentProfile != m_requestedProfile;
+            if (external && !m_externalChangeTimer->isActive()) {
+                m_profileBeforeExternalChange = m_currentProfile;
+            }
+            m_requestedProfile.clear();
             m_currentProfile = newCurrentProfile;
             Q_EMIT currentProfileChanged(m_currentProfile);
+            if (external) {
+                m_externalChangeTimer->start();
+            } else {
+                m_externalChangeTimer->stop();
+            }
         }
     }

@@ -265,6 +299,7 @@ void PowerProfile::readProperties(const QVariantMap &properties)
         QList<QVariantMap> newProfileHolds;
         properties[profileHoldsProperty].value<QDBusArgument>() >> newProfileHolds;
         if (m_profileHolds != newProfileHolds) {
+            m_externalChangeTimer->stop();
             m_profileHolds = newProfileHolds;
             Q_EMIT profileHoldsChanged(m_profileHolds);
         }
diff --git a/daemon/actions/bundled/powerprofile.h b/daemon/actions/bundled/powerprofile.h
index 95e834fd1..509b287b8 100644
--- a/daemon/actions/bundled/powerprofile.h
+++ b/daemon/actions/bundled/powerprofile.h
@@ -11,6 +11,7 @@

 class OrgFreedesktopDBusPropertiesInterface;
 class OrgFreedesktopUPowerPowerProfilesInterface;
+class QTimer;

 namespace PowerDevil::BundledActions
 {
@@ -62,6 +63,7 @@ private Q_SLOTS:
 private:
     void readProperties(const QVariantMap &properties);
     void serviceUnregistered(const QString &name);
+    void showIndicator(const QString &profile);

     OrgFreedesktopUPowerPowerProfilesInterface *m_powerProfilesInterface;
     OrgFreedesktopDBusPropertiesInterface *m_powerProfilesPropertiesInterface;
@@ -74,6 +76,9 @@ private:
     QMultiMap<QString, unsigned int> m_holdMap;

     QString m_configuredProfile;
+    QString m_requestedProfile;
+    QString m_profileBeforeExternalChange;
+    QTimer *m_externalChangeTimer;
 };

 } // namespace PowerDevil::BundledActions
